import java.io.*; import java.util.*; import java.util.stream.*; class Result { static class Plus { int r, c, s, area; Set<Integer> cells; Plus(int r, int c, int s, Set<Integer> cells) { this.r = r; this.c = c; this.s = s; this.area = 4 * s + 1; this.cells = cells; } } public static int twoPluses(List<String> grid) { int n = grid.size(); int m = grid.get(0).length(); List<Plus> pluses = new ArrayList<>(); for (int r = 0; r < n; r++) { for (int c = 0; c < m; c++) { if (grid.get(r).charAt(c) == 'G') { int s = 0; while (true) { int nr = r, nc = c; if (r - s < 0 || r + s >= n || c - s < 0 || c + s >= m || grid.get(r - s).charAt(c) != 'G' || grid.get(r + s).charAt(c) != 'G' || grid.get(r).charAt(c - s) != 'G' || grid.get(r).charAt(c + s) != 'G') break; Set<Integer> cells = new HashSet<>(); for (int i = 0; i <= s; i++) { cells.add((r - i) * m + c); cells.add((r + i) * m + c); cells.add(r * m + (c - i)); cells.add(r * m + (c + i)); } pluses.add(new Plus(r, c, s, cells)); s++; } } } } int maxProduct = 0; for (int i = 0; i < pluses.size(); i++) { for (int j = i + 1; j < pluses.size(); j++) { Plus p1 = pluses.get(i); Plus p2 = pluses.get(j); boolean overlap = false; for (int cell : p1.cells) { if (p2.cells.contains(cell)) { overlap = true; break; } } if (!overlap) { maxProduct = Math.max(maxProduct, p1.area * p2.area); } } } return maxProduct; } } public class Solution { public static void main(String[] args) throws IOException { BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in)); BufferedWriter bufferedWriter = new BufferedWriter(new FileWriter(System.getenv("OUTPUT_PATH"))); String[] firstMultipleInput = bufferedReader.readLine().replaceAll("\\s+$", "").split(" "); int n = Integer.parseInt(firstMultipleInput[0]); int m = Integer.parseInt(firstMultipleInput[1]); List<String> grid = IntStream.range(0, n).mapToObj(i -> { try { return bufferedReader.readLine(); } catch (IOException ex) { throw new RuntimeException(ex); } }).collect(Collectors.toList()); int result = Result.twoPluses(grid); bufferedWriter.write(String.valueOf(result)); bufferedWriter.newLine(); bufferedReader.close(); bufferedWriter.close(); } }